                rowData[`DG-${i} Run Min`] = Number(calc[`DG-${i} Run Min`] || 0).toFixed(2);
                rowData[`DG-${i} Fuel Opening`] = Number(calc[`DG-${i} Fuel Opening`] || 0).toFixed(2);
                rowData[`DG-${i} Fuel Closing`] = Number(calc[`DG-${i} Fuel Closing`] || 0).toFixed(2);
